def canReach(arr: list[int], start: int) -> bool:
    from collections import deque
    n = len(arr)
    q = deque([start])
    visited = {start}
    while q:
        curr = q.popleft()
        if arr[curr] == 0: return True
        for nxt in (curr + arr[curr], curr - arr[curr]):
            if 0 <= nxt < n and nxt not in visited:
                visited.add(nxt)
                q.append(nxt)
    return False

